<?php
declare(strict_types=1);ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();date_default_timezone_set('Asia/Tehran');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);require_once __DIR__.'/backup_lib.php';ts_schedule_auto_backup($pdo);require_once __DIR__.'/sms_lib.php';}catch(Throwable $e){exit('اتصال پایگاه داده برقرار نیست.');}
$currentAdmin=ts_require_roles($pdo,['owner','manager','staff']);function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}function toman($n){return number_format((int)$n).' تومان';}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('درخواست نامعتبر');}$action=(string)($_POST['action']??'');$orderId=max(0,(int)($_POST['order_id']??0));
  if($action==='toggle_item'){$itemId=max(0,(int)($_POST['item_id']??0));$st=$pdo->prepare('SELECT oi.id,oi.order_id,oi.picked,o.status FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.id=? AND oi.order_id=?');$st->execute([$itemId,$orderId]);$it=$st->fetch();if($it&&$it['status']!=='cancelled'){$new=(int)!((int)$it['picked']);$u=$pdo->prepare('UPDATE order_items SET picked=?,picked_at=? WHERE id=?');$u->execute([$new,$new?date('Y-m-d H:i:s'):null,$itemId]);$cst=$pdo->prepare('SELECT COUNT(*) total,SUM(picked=1) picked FROM order_items WHERE order_id=?');$cst->execute([$orderId]);$cnt=$cst->fetch();if((int)$cnt['total']>0&&(int)$cnt['total']===(int)$cnt['picked']){$pdo->prepare("UPDATE orders SET status='ready',status_updated_at=NOW() WHERE id=? AND status IN ('new','confirmed','preparing','ready')")->execute([$orderId]);ts_sms_order_event($pdo,$orderId,'ready');ts_process_sms_queue($pdo,2);}else{$pdo->prepare("UPDATE orders SET status='preparing',status_updated_at=NOW() WHERE id=? AND status='ready'")->execute([$orderId]);}}header('Location:admin_orders.php#order-'.$orderId);exit;}
  if($action==='set_status'){$new=(string)($_POST['status']??'new');$allowed=['new','confirmed','preparing','ready','out','delivered','cancelled'];if(!in_array($new,$allowed,true))$new='new';try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT status,stock_restored_at FROM orders WHERE id=? FOR UPDATE');$st->execute([$orderId]);$o=$st->fetch();if(!$o)throw new RuntimeException('سفارش پیدا نشد.');$old=(string)$o['status'];if($old==='cancelled'&&$new!=='cancelled')throw new RuntimeException('سفارش لغوشده را دوباره فعال نکنید؛ سفارش جدید ثبت شود.');if($new==='cancelled'&&$old!=='cancelled'){
    $q=$pdo->prepare('SELECT product_id,quantity FROM order_items WHERE order_id=?');$q->execute([$orderId]);$up=$pdo->prepare('UPDATE products SET stock=stock+?,updated_at=NOW() WHERE id=?');if(empty($o['stock_restored_at']))foreach($q->fetchAll() as $it)$up->execute([(int)$it['quantity'],(int)$it['product_id']]);$pdo->prepare("UPDATE orders SET status='cancelled',stock_restored_at=COALESCE(stock_restored_at,NOW()),status_updated_at=NOW() WHERE id=?")->execute([$orderId]);
    }else{$pdo->prepare('UPDATE orders SET status=?,status_updated_at=NOW() WHERE id=?')->execute([$new,$orderId]);if($new==='delivered')$pdo->prepare('UPDATE order_items SET picked=1,picked_at=COALESCE(picked_at,NOW()) WHERE order_id=?')->execute([$orderId]);}$pdo->commit();if(in_array($new,['ready','out','delivered','cancelled'],true)){ts_sms_order_event($pdo,$orderId,$new);ts_process_sms_queue($pdo,2);}$msg='وضعیت سفارش ذخیره شد.';}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$err=$x->getMessage();}}
}
$filter=(string)($_GET['status']??'active');$where='1=1';$params=[];if($filter==='active')$where="o.status NOT IN ('delivered','cancelled')";elseif(in_array($filter,['new','confirmed','preparing','ready','out','delivered','cancelled'],true)){$where='o.status=?';$params[]=$filter;}
$st=$pdo->prepare("SELECT o.*,c.name customer_name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE $where ORDER BY FIELD(o.status,'new','confirmed','preparing','ready','out','delivered','cancelled'),o.id DESC LIMIT 200");$st->execute($params);$orders=$st->fetchAll();$items=[];if($orders){$ids=array_column($orders,'id');$ph=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT oi.*,p.image_path,p.pyramid_code2,COALESCE(oi.barcode,p.barcode) show_barcode FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id IN ($ph) ORDER BY oi.id");$q->execute($ids);foreach($q->fetchAll() as $it)$items[(int)$it['order_id']][]=$it;}
$labels=['new'=>'جدید','confirmed'=>'تأیید','preparing'=>'جمع‌آوری','ready'=>'آماده','out'=>'در مسیر','delivered'=>'تحویل','cancelled'=>'لغو'];
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>جمع‌آوری سفارش‌ها | مدیریت</title><link rel="stylesheet" href="assets/style.css?v=20261024-orders"><style>.ops{max-width:980px;margin:20px auto;padding:0 14px}.filters{display:flex;gap:7px;overflow:auto;padding-bottom:8px}.filters a{white-space:nowrap;background:#fff;border:1px solid #e4ebe5;padding:8px 11px;border-radius:999px}.filters a.active{background:#11823b;color:#fff}.order-card{background:#fff;border:1px solid #e3ebe5;border-radius:18px;margin:14px 0;padding:15px;box-shadow:0 4px 18px #1831260a}.order-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.order-meta{font-size:12px;color:#718078;line-height:1.8}.pick-progress{height:8px;border-radius:8px;background:#edf2ee;overflow:hidden;margin:10px 0}.pick-progress i{display:block;height:100%;background:#11823b}.pick-item{display:grid;grid-template-columns:64px 1fr auto;gap:10px;align-items:center;padding:10px 0;border-top:1px solid #eef1ef}.pick-item img,.pick-photo{width:60px;height:60px;object-fit:contain;border-radius:10px;border:1px solid #e7ece8}.picked{opacity:.55}.picked .item-name{text-decoration:line-through}.item-name{font-weight:800}.barcode{display:inline-block;font-family:monospace;direction:ltr;background:#f3f6f3;padding:3px 6px;border-radius:6px;font-size:11px}.pick-btn{min-width:82px}.pick-btn.done{background:#e5f5e8;color:#11823b}.status-row{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.status-row form{margin:0}.status-row button{padding:8px 10px;font-size:11px}.customer-box{background:#f7faf7;border-radius:12px;padding:10px;margin-top:10px;font-size:12px;line-height:1.8}.print-btn{background:#eef5ff;color:#245a9a}.danger{background:#fff0ee;color:#a62a22}.empty{padding:35px;text-align:center}@media(max-width:650px){.ops{padding:0 9px}.pick-item{grid-template-columns:52px 1fr}.pick-item img,.pick-photo{width:50px;height:50px}.pick-item .pick-btn{grid-column:1/-1;width:100%}.order-top{flex-direction:column}.status-row button{flex:1}.top .brand small{display:none}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">🧺</span><span><b>جمع‌آوری سفارش‌ها</b><small>کار روزانه فروشگاه</small></span></a><?php if(($currentAdmin['role']??'')==='staff'):?><a class="btn pale" href="admin_logout.php">خروج</a><?php else:?><div style="display:flex;gap:6px"><a class="btn pale" href="admin_couriers.php">🛵 پیک‌ها</a><a class="btn pale" href="admin.php">مدیریت اصلی</a></div><?php endif;?></header><main class="ops"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><div class="filters"><?php foreach(['active'=>'فعال','new'=>'جدید','preparing'=>'جمع‌آوری','ready'=>'آماده','out'=>'در مسیر','delivered'=>'تحویل‌شده','cancelled'=>'لغوشده'] as $k=>$v):?><a class="<?=$filter===$k?'active':''?>" href="admin_orders.php?status=<?=e($k)?>"><?=e($v)?></a><?php endforeach;?></div><?php if(!$orders):?><div class="panel empty">سفارشی در این بخش نیست.</div><?php endif;?><?php foreach($orders as $o):$its=$items[(int)$o['id']]??[];$picked=0;foreach($its as $x)$picked+=(int)$x['picked'];$total=count($its);$pct=$total?round($picked/$total*100):0;?><article class="order-card" id="order-<?=(int)$o['id']?>"><div class="order-top"><div><h2 style="margin:0">سفارش #<?=(int)$o['id']?> · <?=e($labels[$o['status']]??$o['status'])?></h2><div class="order-meta"><?=e($o['created_at'])?> · <?=e($o['delivery_slot'])?></div></div><div><b><?=toman($o['total'])?></b><br><button class="btn print-btn" type="button" onclick="printCard(<?=(int)$o['id']?>)">🖨 چاپ</button></div></div><div class="pick-progress"><i style="width:<?=$pct?>%"></i></div><div class="muted"><?=$picked?> از <?=$total?> قلم جمع‌آوری شده</div><?php foreach($its as $it):?><div class="pick-item <?=$it['picked']?'picked':''?>"><?php if(!empty($it['image_path'])):?><img src="<?=e($it['image_path'])?>" alt=""><?php else:?><div class="pick-photo" style="display:grid;place-items:center">🛒</div><?php endif;?><div><div class="item-name"><?=e($it['product_name'])?></div><div><?=number_format((int)$it['quantity'])?> عدد × <?=toman($it['unit_price'])?></div><span class="barcode"><?=e($it['show_barcode']?:'بدون بارکد')?></span><?php if(!empty($it['pyramid_code2'])):?><span class="muted"> · Code2: <?=e($it['pyramid_code2'])?></span><?php endif;?></div><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="toggle_item"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><input type="hidden" name="item_id" value="<?=(int)$it['id']?>"><button class="btn pick-btn <?=$it['picked']?'done':''?>"><?=$it['picked']?'✓ برداشتم':'برداشتم'?></button></form></div><?php endforeach;?><div class="customer-box"><b><?=e($o['customer_name'])?></b> · <a href="tel:<?=e($o['phone'])?>"><?=e($o['phone'])?></a><br><?=e($o['address'])?></div><div class="status-row"><?php if(in_array(($currentAdmin['role']??''),['owner','manager'],true)&&!in_array($o['status'],['cancelled','delivered'],true)):?><a class="btn pale" href="admin_order_edit.php?order_id=<?=(int)$o['id']?>">✏️ اصلاح اقلام</a><?php endif;?><?php foreach(['confirmed'=>'تأیید','preparing'=>'جمع‌آوری','ready'=>'آماده','out'=>'ارسال شد','delivered'=>'تحویل شد'] as $k=>$v):?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="set_status"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><input type="hidden" name="status" value="<?=e($k)?>"><button class="btn <?=$o['status']===$k?'pale':''?>"><?=e($v)?></button></form><?php endforeach;?><?php if($o['status']!=='cancelled'&&$o['status']!=='delivered'):?><form method="post" onsubmit="return confirm('سفارش لغو شود و موجودی همه کالاها به فروشگاه برگردد؟');"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="set_status"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><input type="hidden" name="status" value="cancelled"><button class="btn danger">لغو + برگشت موجودی</button></form><?php endif;?></div></article><?php endforeach;?></main><script>function printCard(id){const el=document.getElementById('order-'+id);if(!el)return;const w=window.open('','_blank','width=700,height=900');w.document.write('<meta charset="utf-8"><title>سفارش '+id+'</title><style>body{font-family:Tahoma;direction:rtl;padding:20px}.pick-btn,.status-row,.print-btn{display:none}.pick-item{display:grid;grid-template-columns:60px 1fr;gap:10px;border-top:1px solid #ddd;padding:10px}.pick-item img,.pick-photo{width:55px;height:55px;object-fit:contain}.barcode{font-family:monospace;direction:ltr}.customer-box{margin-top:15px}</style>'+el.outerHTML);w.document.close();w.focus();setTimeout(()=>w.print(),300);}</script><script src="assets/order-alert.js?v=20261024"></script><script src="assets/admin_push.js?v=20261024-bgpush"></script></body></html>
